SELECT "TableroSistemaPenal_6"."PAIS" AS "PAIS",   "TableroSistemaPenal_6"."TIP_TRIB" AS "TIP_TRIB",   SUM(CAST("TableroSistemaPenal_6"."Number_of_Records" AS BIGINT)) AS "sum_Number_of_Records_ok",   CAST(EXTRACT(YEAR FROM "TableroSistemaPenal_6"."FECHA_AUDIENCIA") AS BIGINT) AS "yr_FECHA_AUDIENCIA_ok" FROM "TableroSistemaPenal_6" GROUP BY "TableroSistemaPenal_6"."PAIS",   "TableroSistemaPenal_6"."TIP_TRIB", "yr_FECHA_AUDIENCIA_ok";
